// The customers on the call list. Fixed for now (2026-10-29, from the
// user; 58688 added the same day); later this comes from a HubSpot list or
// a rep's filter.
const CONFIG = {
  ids: [58856, 58854, 58853, 58851, 58759, 58740, 58724, 58688, 58650, 58595],
};
return { ids: CONFIG.ids.map(String) };

// HubSpot customers (0-2) → the call list, in Config's order. Property
// names read from Fairbank's HubSpot on 2026-10-29: all_phones ("All
// Phones", shown as Phone Numbers), ai_customer_insights ("Customer
// Insights (demo data)"), createdate, address, city, state.
const ids = $('Config').first().json.ids;
const r = $input.first().json;
if (r.error) {
  return { statusCode: 502, body: { error: 'HubSpot customer read failed: ' + String(r.error.message || r.error), step: 'HubSpot: read customers' } };
}
const s = (v) => (v == null ? '' : String(v)).trim();
const byId = {};
for (const row of (Array.isArray(r.results) ? r.results : [])) {
  const p = row.properties || {};
  if (p.e_customer_id) byId[s(p.e_customer_id)] = row;
}
const customers = ids.filter((id) => byId[id]).map((id) => {
  const row = byId[id];
  const p = row.properties || {};
  return {
    hs_id: s(row.id),
    e_customer_id: id,
    name: s(p.name) || ('Customer ' + id),
    // All Phones holds every number on one line; split on ; , or a line break.
    phones: s(p.all_phones).split(/\s*(?:;|\n|,)\s*/).filter(Boolean),
    insights: s(p.ai_customer_insights),
    create_date: s(p.createdate),
    street: s(p.address),
    city: s(p.city),
    state: s(p.state),
  };
});
return { statusCode: 200, body: { success: true, customers, missing: ids.filter((id) => !byId[id]) } };
